// Conversion du payload MQTT
let data = msg.payload.toString().trim();

// Device:esp32h2-102,Temp:22.0,Hum:50.0,Son:705

let sensor = {};
data.split(",").forEach(part => {
    let [key, value] = part.split(":");
    if (!key || !value) {
        return;
    }
    key = key.trim();
    value = value.trim();
    switch (key) {

        case "Device":
            sensor.deviceId = value;
            break;

        case "Temp":
            sensor.temperature = Number(value);
            break;

        case "Hum":
            sensor.humidity = Number(value);
            break;

        case "Son":
            sensor.sound = Number(value);
            break;
    }
});

// Ajout date/heure
let now = new Date();
sensor.timestamp = now;

// Optionnel : format lisible
sensor.date = now.toISOString();

// Vérification
if (!sensor.deviceId) {
    node.error("Message capteur invalide : " + data);
    return null;
}


// Envoi vers MongoDB
msg.payload = [sensor];

return msg;

